-- SEO site plan (2026-10-07): blog columns + 20 unpublished drafts.
-- 1) Blog columns (migration 20260512000000, never applied to project khxkorrvylcscyqfklxi)
BEGIN;
-- GEO / LLM SEO upgrade for the blogs table.
-- This migration is purely additive: it does not drop, rename or change the
-- type of any existing column. Existing inserts/selects keep working.
--
-- New columns:
--   category          - optional taxonomy used by the public blog UI and JSON-LD
--   slug              - stable, indexable URL slug (generated on first save)
--   meta_description  - optional override of `excerpt` for <meta name="description">
--   is_published      - publish toggle (defaults to true so existing rows remain visible)

ALTER TABLE public.blogs
  ADD COLUMN IF NOT EXISTS category text,
  ADD COLUMN IF NOT EXISTS slug text,
  ADD COLUMN IF NOT EXISTS meta_description text,
  ADD COLUMN IF NOT EXISTS is_published boolean NOT NULL DEFAULT true;

-- Freeze the slugs the live site already serves (same algorithm as generateBlogSlug in src/lib/slugUtils.ts),
-- so URLs Google has indexed keep working.
UPDATE public.blogs SET slug = $bmsq$the-sleep-money-strategy-designing-your-app-for-true-recurring-revenue-general-passive-income-2025$bmsq$ WHERE id = 'd1076464-a6e6-44d2-b34a-cbf42e355f41' AND (slug IS NULL OR slug = '');
UPDATE public.blogs SET slug = $bmsq$beyond-products-why-founders-need-infrastructure-not-just-apps-general-app-developement-2025$bmsq$ WHERE id = 'e0ea656d-a325-4481-a32d-4b1c3d923454' AND (slug IS NULL OR slug = '');
UPDATE public.blogs SET slug = $bmsq$why-2026-is-the-year-to-launch-your-own-app-business-general-2026-2025$bmsq$ WHERE id = '7822fd99-cf2f-47a1-a1d7-7bb236222fb4' AND (slug IS NULL OR slug = '');
UPDATE public.blogs SET slug = $bmsq$beyond-50-employees-how-to-scale-your-remote-team-management-general-remote-team-management-2025$bmsq$ WHERE id = '896b0a03-61f4-4cab-80ce-8d4ee87be871' AND (slug IS NULL OR slug = '');
UPDATE public.blogs SET slug = $bmsq$the-modern-b2b-saas-marketing-blueprint-general-b2b-saas-marketing-2025$bmsq$ WHERE id = '6cf86aa6-6495-4667-a6da-d5d29cec7750' AND (slug IS NULL OR slug = '');
UPDATE public.blogs SET slug = $bmsq$your-sales-team-is-wasting-20-of-their-week-heres-the-fix-general-sales-automation-2025$bmsq$ WHERE id = '348f43e3-05fd-4a44-95f5-6e82ec9d57ba' AND (slug IS NULL OR slug = '');
UPDATE public.blogs SET slug = $bmsq$why-traditional-project-management-fails-modern-agencies-general-project-management-2025$bmsq$ WHERE id = '0bcb7449-b7b7-4e37-9782-292db10b78cf' AND (slug IS NULL OR slug = '');
UPDATE public.blogs SET slug = $bmsq$how-dual-interface-project-management-tools-are-transforming-client-relationships-general-agency-tools-2025$bmsq$ WHERE id = 'be657919-0d71-4a56-8412-77673cb354be' AND (slug IS NULL OR slug = '');
UPDATE public.blogs SET slug = $bmsq$how-to-boost-remote-team-productivity-by-40-without-micromanaging-general-saas-2025$bmsq$ WHERE id = 'ea4891d0-c219-4289-a9ae-6c7dfa084fe4' AND (slug IS NULL OR slug = '');
UPDATE public.blogs SET slug = $bmsq$is-your-sales-pipeline-leaking-stop-lead-decay-with-smart-automation-general-sales-automation-2025$bmsq$ WHERE id = 'd1a75b49-e9d4-42b4-994a-cf773c22b758' AND (slug IS NULL OR slug = '');
UPDATE public.blogs SET slug = $bmsq$how-to-boost-remote-team-productivity-by-40-without-micromanaging-general-team-management-2025$bmsq$ WHERE id = '18392150-5fc5-43ac-a34c-3d1646fbe5cb' AND (slug IS NULL OR slug = '');
UPDATE public.blogs SET slug = $bmsq$how-modern-founders-launch-faster-and-smarter-with-ai-powered-business-infrastructure-general-ai-business-tools-2025$bmsq$ WHERE id = '58ce1ab6-bd8f-4575-9b7c-c0f89c75914d' AND (slug IS NULL OR slug = '');
UPDATE public.blogs SET slug = $bmsq$how-ai-automation-is-reshaping-the-future-of-work-general-ai-2025$bmsq$ WHERE id = 'd7ec454b-88a7-441a-83f9-7092fdf04c1b' AND (slug IS NULL OR slug = '');
UPDATE public.blogs SET slug = $bmsq$the-ai-revolution-how-machine-learning-is-transforming-web-development-general-ai-2024$bmsq$ WHERE id = 'b17b201b-00e8-4768-b851-f3916becf9e0' AND (slug IS NULL OR slug = '');
UPDATE public.blogs SET slug = $bmsq$progressive-web-apps-the-future-of-mobile-first-development-general-pwa-2024$bmsq$ WHERE id = '8c1dc1f9-2911-4490-aacb-2db1b139fdd0' AND (slug IS NULL OR slug = '');
UPDATE public.blogs SET slug = $bmsq$scaling-saas-applications-lessons-from-building-enterprise-solutions-general-saas-2024$bmsq$ WHERE id = '2291db02-2e96-42c0-ae42-35797ba88658' AND (slug IS NULL OR slug = '');
UPDATE public.blogs SET slug = $bmsq$react-performance-optimization-advanced-techniques-for-2024-general-react-2023$bmsq$ WHERE id = 'f2a28ef3-ca55-4de1-8458-81de252cabd6' AND (slug IS NULL OR slug = '');
UPDATE public.blogs SET slug = $bmsq$cybersecurity-best-practices-for-modern-web-applications-general-security-2023$bmsq$ WHERE id = '878d542b-9e8f-4cfc-8175-966285150f48' AND (slug IS NULL OR slug = '');
UPDATE public.blogs SET slug = $bmsq$case-study-transforming-e-commerce-with-headless-architecture-general-e-commerce-2023$bmsq$ WHERE id = 'a7c325f2-96f3-4e4a-b6f7-82336c3874c9' AND (slug IS NULL OR slug = '');

-- Backfill stable slugs for any existing rows that do not have one yet.
-- Format mirrors generateBlogSlug() in src/lib/slugUtils.ts but is computed
-- once in SQL so the URL is FROZEN even if the title or tags later change.
UPDATE public.blogs
SET slug = trim(both '-' from regexp_replace(
  lower(coalesce(title, '') || '-' || coalesce(category, 'general') || '-' ||
        coalesce((tags)[1], '') || '-' || coalesce(left(published_date::text, 4), '')),
  '[^a-z0-9]+', '-', 'g'
))
WHERE slug IS NULL OR length(slug) = 0;

-- Unique index on slug (partial so legacy rows with NULL never collide).
CREATE UNIQUE INDEX IF NOT EXISTS blogs_slug_unique_idx
  ON public.blogs (slug)
  WHERE slug IS NOT NULL;

-- Helpful index for the published-only public listing.
CREATE INDEX IF NOT EXISTS blogs_is_published_published_date_idx
  ON public.blogs (is_published, published_date DESC);

-- NOTE on RLS:
-- We intentionally do NOT change the existing "Public can view published blogs"
-- policy (USING (true)) defined in 20250801062649. The application layer is
-- responsible for filtering is_published=true on the public read path so that
-- this migration cannot accidentally hide previously visible rows.

COMMIT;

-- 2) 20 blog drafts by Kavya, unpublished until a team member adds the real example and publishes
BEGIN;
INSERT INTO public.blogs (title, slug, excerpt, meta_description, content, author, published_date, reading_time, tags, image, category, is_published)
SELECT $bmsq$How to get clients for your business in 2026: 12 ways that work$bmsq$, $bmsq$how-to-get-clients-for-your-business$bmsq$, $bmsq$12 practical ways to get clients in 2026, from referrals and Google to ads that open WhatsApp, and how to choose the two or three that fit your business.$bmsq$, $bmsq$12 practical ways to get clients in 2026, from referrals and Google to ads that open WhatsApp, and how to choose the two or three that fit your business.$bmsq$, $bmsq$<p>The most reliable way to get clients in 2026 is to combine one paid channel that reaches new buyers (Meta, Google or LinkedIn ads), one free channel that compounds (referrals, Google Business Profile or content), and fast follow-up on every enquiry. Pick two or three of the 12 methods below, run them properly for 90 days, and judge them on cost per booked meeting, not likes or clicks.</p><p>Most small businesses do not have a lead problem. They have a consistency problem. They try a channel for three weeks, reply to enquiries the next day, and decide "ads don't work for us". The list below is ordered roughly from cheapest to most involved, so you can start at the top and work down.</p><h2>The 12 ways at a glance</h2><table><thead><tr><th>Method</th><th>Best for</th><th>Speed to first enquiry</th><th>Main cost</th></tr></thead><tbody><tr><td>1. Structured referrals</td><td>Any business with happy clients</td><td>Days to weeks</td><td>Your time</td></tr><tr><td>2. Google Business Profile</td><td>Local services, clinics, shops</td><td>Weeks</td><td>Your time</td></tr><tr><td>3. Reactivating old leads</td><td>Anyone with a contact list</td><td>Days</td><td>Your time, messaging fees</td></tr><tr><td>4. Meta ads that open WhatsApp</td><td>Consumer and SMB buyers</td><td>Days</td><td>Ad spend</td></tr><tr><td>5. Google search ads</td><td>Urgent, high-intent services</td><td>Days</td><td>Ad spend</td></tr><tr><td>6. LinkedIn outreach</td><td>B2B, high ticket</td><td>Weeks</td><td>Time or tools</td></tr><tr><td>7. Instant lead response</td><td>Everyone running ads</td><td>Immediate effect</td><td>Process or automation</td></tr><tr><td>8. Follow-up sequences</td><td>Longer decisions</td><td>Weeks</td><td>Setup time</td></tr><tr><td>9. Partnerships</td><td>Businesses with natural partners</td><td>Weeks to months</td><td>Relationship time</td></tr><tr><td>10. Answer-first content</td><td>Expertise-led businesses</td><td>Months</td><td>Writing or video time</td></tr><tr><td>11. Small events and webinars</td><td>Education, B2B, finance</td><td>Weeks</td><td>Time, some ad spend</td></tr><tr><td>12. Measuring and cutting</td><td>Everyone</td><td>Ongoing</td><td>Discipline</td></tr></tbody></table><h2>1. Turn referrals into a system</h2><p>Most owners say referrals are their best source, then never ask for them. Make it a step in delivery. Ask at the moment a client is happiest: the day the project goes live, the week a patient feels better, the day a tax return is filed. Send a short WhatsApp message with a ready-to-forward line they can copy. Keep a simple sheet of who referred whom and thank them every time.</p><h2>2. Fix your Google Business Profile</h2><p>If people search "near me" for what you do, your profile is often the first thing they see. Fill every field, choose the right primary category, add real photos, list services with prices or ranges, and reply to every review. Ask each satisfied client for a review with a direct link. This costs nothing but time, and it supports every other channel, because people check your reviews after seeing an ad.</p><h2>3. Reactivate leads you already paid for</h2><p>Look at enquiries from the last 12 months that never converted. Many were simply bad timing. Send a short, personal message: what has changed, one useful offer, and a question that is easy to answer. Respect opt-outs and only message people who gave you their number for this purpose.</p><h2>4. Run Meta ads that open a WhatsApp chat</h2><p>For Indian SMB buyers, a chat often feels easier than a form. Click-to-WhatsApp ads let someone tap and start a conversation in the app they already use. The trade-off is that you must answer quickly and qualify inside the chat. Our <a href="/blog/click-to-whatsapp-ads-setup-guide">click-to-WhatsApp setup guide</a> covers the scripts.</p><h2>5. Use Google search ads for urgent intent</h2><p>When someone types "CA for GST registration" or "dentist open now", they want help today. Search ads catch that intent. Start with a tight list of exact and phrase match keywords, add negatives every week, and send traffic to a page that matches the search.</p><h2>6. Do focused LinkedIn outreach for B2B</h2><p>If your buyer has a job title, LinkedIn lets you reach them directly. Keep the list small and specific, personalise the first line, and offer something useful before asking for a call.</p><h2>7. Reply to every lead within minutes</h2><p>A lead who filled a form is comparing you with two or three others. The first business to respond with something helpful usually gets the conversation. Set up an instant acknowledgement on WhatsApp and a human or AI follow-up shortly after. Read <a href="/blog/how-fast-should-you-reply-to-a-lead">how fast you should reply to a lead</a> for a simple way to measure this.</p><h2>8. Build follow-up sequences</h2><p>Many buyers need several touches before they book. A sequence of short WhatsApp and email messages over two to three weeks, each with a reason to reply, recovers leads that would otherwise go quiet. Stop the sequence the moment they respond.</p><h2>9. Partner with businesses that serve the same buyer</h2><p>An interior designer and a modular kitchen supplier. A CA and a company registration consultant. A coaching institute and a school counsellor. Agree a simple, written referral arrangement and share leads both ways.</p><h2>10. Publish content that answers real questions</h2><p>Write down the ten questions prospects ask on every sales call. Answer each in a short article or video. This builds trust slowly but keeps working, and it gives your sales team links to send.</p><h2>11. Run small events and webinars</h2><p>A 30-minute online session on one specific problem attracts people who care about it. Collect registrations, follow up with the recording, and invite attendees to a short consultation.</p><h2>12. Measure, then cut what does not work</h2><p>Track every lead's source, whether they replied, whether they booked, and whether they paid. After 90 days, stop the weakest channel and move its budget or time to the strongest.</p><p><strong>[EDITOR: add one real example and screenshot here — client name only with written permission]</strong></p><h2>How to choose your first three</h2><ul><li>If you have past clients, start with referrals and reactivation. They are the cheapest.</li><li>If buyers search for you when they have a problem, add Google search ads and your Business Profile.</li><li>If buyers do not search but respond to a good offer, add Meta ads that open WhatsApp.</li><li>If you sell to companies, add LinkedIn outreach.</li><li>Whatever you choose, fix response time first. Every other method depends on it.</li></ul><p>BoostMySites is an <a href="/">AI client acquisition system</a> that brings several of these together: ads on Meta, Google, LinkedIn and other platforms, run in your own ad accounts, with AI follow-up on WhatsApp and email and leads scored into a CRM. Campaigns stay paused until you approve them.</p><h2>FAQ</h2><h3>What is the fastest way to get clients for a new business?</h3><p>Start with people who already know you: past colleagues, past clients and your personal network. In parallel, run a small paid campaign to a clear offer so you learn what message works. Organic content is valuable but slow, so do not rely on it alone in the first few months.</p><h3>How many marketing channels should a small business use?</h3><p>Two or three, run properly, beat eight run badly. Choose one paid channel, one free channel and a follow-up process, then add more only after the first ones are measured and stable.</p><h3>How long before I know if a channel is working?</h3><p>Give a channel enough time and budget to produce a meaningful number of conversations, which for most small businesses means at least several weeks. Judge it on booked meetings and paying clients, not on clicks.</p><p>Want a plan for which of these 12 methods fit your business and budget? <a href="/#contact-form">Get my client acquisition plan</a> and we will map it out with you.</p>$bmsq$, $bmsq${"name": "Kavya Shree.R", "avatar": "https://www.boostmysites.com/team/kavya.jpg", "bio": "Kavya Shree.R is Chief Marketing Officer at BoostMySites and runs the blog's content calendar. She writes about getting clients with ads, WhatsApp and follow-up systems for growing businesses."}$bmsq$::jsonb, '2026-10-12T03:30:00.000Z', 6, ARRAY[$bmsq$Getting clients$bmsq$,$bmsq$Lead generation$bmsq$,$bmsq$Small business$bmsq$]::text[], 'https://www.boostmysites.com/brand/hero-poster.jpg', $bmsq$Getting clients$bmsq$, false
WHERE NOT EXISTS (SELECT 1 FROM public.blogs WHERE slug = $bmsq$how-to-get-clients-for-your-business$bmsq$);

INSERT INTO public.blogs (title, slug, excerpt, meta_description, content, author, published_date, reading_time, tags, image, category, is_published)
SELECT $bmsq$Meta ads cost in India: real numbers by industry$bmsq$, $bmsq$meta-ads-cost-india$bmsq$, $bmsq$What Meta ads really cost in India, what drives cost per lead in each industry, and a simple formula to work out a realistic monthly budget.$bmsq$, $bmsq$What Meta ads really cost in India, what drives cost per lead in each industry, and a simple formula to work out a realistic monthly budget.$bmsq$, $bmsq$<p>Meta ads in India have no fixed price: you pay in an auction, so your cost per lead depends on your industry, city, audience, offer and how fast you follow up. The useful number is not "cost per click" but cost per qualified lead and cost per paying client, and you can estimate both before you spend with the simple formula below.</p><p>Any article that gives one national figure for "Meta ads cost in India" is either averaging very different businesses or guessing. A real estate project in Bengaluru and a home tuition service in a tier-3 town are in completely different auctions. So this post explains what moves the price, shows you how to calculate your own budget, and then shares figures from accounts we manage.</p><h2>What actually drives Meta ad costs</h2><ul><li><strong>Competition for your audience.</strong> Meta charges based on how many advertisers want the same people at the same time. Audiences many businesses chase cost more.</li><li><strong>Season and festivals.</strong> Costs often rise around big shopping periods because ecommerce brands flood the auction.</li><li><strong>Ad quality and relevance.</strong> Meta favours ads people engage with. A weak creative can cost more for the same reach.</li><li><strong>Objective.</strong> Optimising for leads or conversations costs more per result than optimising for clicks, but the results are closer to revenue.</li><li><strong>Offer strength.</strong> "Free site visit with transport" will convert differently from "Contact us for details".</li><li><strong>Form friction.</strong> Short instant forms bring more, cheaper, lower-quality leads. Higher-intent forms bring fewer, better ones.</li><li><strong>Location.</strong> Metro audiences are often contested by more advertisers than smaller cities.</li></ul><h2>The formula: work backwards from revenue</h2><p>Instead of asking "how much should I spend", ask "how much can I afford to pay for one client". Then work backwards.</p><ol><li><strong>Value of one client.</strong> Average first-order revenue, or better, gross profit.</li><li><strong>Affordable cost per client.</strong> The share of that profit you are willing to spend to win the client.</li><li><strong>Close rate.</strong> Out of every 10 qualified leads, how many pay?</li><li><strong>Affordable cost per lead</strong> = affordable cost per client × close rate.</li><li><strong>Monthly budget</strong> = affordable cost per lead × number of leads your team can handle.</li></ol><h3>Worked example (hypothetical numbers)</h3><p>These numbers are an example only, to show the maths. They are not benchmarks.</p><table><thead><tr><th>Input</th><th>Example value</th></tr></thead><tbody><tr><td>Gross profit per new client</td><td>Example: ₹40,000</td></tr><tr><td>Share you will spend to acquire a client</td><td>Example: 25% = ₹10,000</td></tr><tr><td>Close rate from qualified leads</td><td>Example: 1 in 10 (10%)</td></tr><tr><td>Affordable cost per qualified lead</td><td>₹10,000 × 10% = ₹1,000</td></tr><tr><td>Leads your team can follow up per month</td><td>Example: 60</td></tr><tr><td>Monthly ad budget</td><td>₹1,000 × 60 = ₹60,000</td></tr></tbody></table><p>If your first few weeks show a qualified lead costs more than your affordable figure, you have three levers: improve the offer, improve the close rate with faster follow-up, or narrow the audience. Raising the budget does not fix a broken ratio.</p><h2>Figures from accounts we manage</h2><p><strong>[EDITOR: insert our real account data here — cost per lead and cost per qualified lead by industry and city tier, with date range, number of accounts and total spend behind each figure. Only include industries where we have enough data to be meaningful. Do not publish client names.]</strong></p><table><thead><tr><th>Industry</th><th>City tier</th><th>Cost per lead</th><th>Cost per qualified lead</th><th>Date range / sample size</th></tr></thead><tbody><tr><td>Real estate</td><td>[EDITOR]</td><td>[EDITOR]</td><td>[EDITOR]</td><td>[EDITOR]</td></tr><tr><td>Clinics</td><td>[EDITOR]</td><td>[EDITOR]</td><td>[EDITOR]</td><td>[EDITOR]</td></tr><tr><td>Interior design</td><td>[EDITOR]</td><td>[EDITOR]</td><td>[EDITOR]</td><td>[EDITOR]</td></tr><tr><td>Education / coaching</td><td>[EDITOR]</td><td>[EDITOR]</td><td>[EDITOR]</td><td>[EDITOR]</td></tr><tr><td>CA and finance</td><td>[EDITOR]</td><td>[EDITOR]</td><td>[EDITOR]</td><td>[EDITOR]</td></tr></tbody></table><p><strong>[EDITOR: add one real example and screenshot here — client name only with written permission]</strong></p><h2>How industry changes the picture</h2><p>Even without quoting numbers, the pattern across industries is predictable. High-ticket purchases such as property and interiors usually cost more per lead, because fewer people are in the market and the decision is long. That is fine if each sale is worth a lot. Lower-ticket, frequent services such as clinics or tuition can work with cheaper leads but need fast, high-volume follow-up. B2B services such as accounting often see fewer leads from Meta than from Google or LinkedIn, because people do not scroll Instagram looking for an auditor.</p><h2>Common mistakes that inflate cost per lead</h2><ul><li>Judging a campaign in its first few days, before Meta's delivery has settled.</li><li>Running many tiny ad sets that each get too little budget to learn.</li><li>Using the same creative for months until people stop noticing it.</li><li>Counting every form fill as a lead instead of tracking which ones were genuine.</li><li>Replying hours later, so good leads go cold and the cost per client rises.</li></ul><p>If your ads get plenty of clicks but few genuine enquiries, read <a href="/blog/facebook-ads-clicks-but-no-leads">why Facebook ads get clicks but no leads</a>. If you are deciding where to spend, compare channels in <a href="/blog/google-ads-vs-meta-ads-service-businesses">Google ads vs Meta ads for service businesses</a>.</p><h2>How we manage Meta spend</h2><p>Our <a href="/services/ai-ad-campaigns">AI ad campaigns</a> run inside your own Meta ad account and billing, so you see every rupee. Campaigns are staged paused until you approve them. Once live, an optimisation loop runs every 20 minutes, around 72 checks a day, adjusting budgets and pausing weak ads. Results still depend on your offer and market, and no one can guarantee a cost per lead.</p><h2>FAQ</h2><h3>What is a good minimum budget for Meta ads in India?</h3><p>Enough to get a meaningful number of results each week so Meta's system can learn and you can judge the ads. Use the formula above with your own numbers rather than a generic figure. A budget too small to produce regular leads mostly produces noise.</p><h3>Is cost per click a useful number?</h3><p>Only as a diagnostic. Cheap clicks from people who never enquire are expensive. Track cost per qualified lead and cost per paying client instead.</p><h3>Do Meta ads cost the same on Facebook and Instagram?</h3><p>Not necessarily. Both run in the same auction system, but audiences and placements behave differently. Let Meta test placements at first, then review which ones produce qualified leads for you.</p><p>Want a budget worked out from your own margins and close rate? <a href="/#contact-form">Get my client acquisition plan</a>.</p>$bmsq$, $bmsq${"name": "Kavya Shree.R", "avatar": "https://www.boostmysites.com/team/kavya.jpg", "bio": "Kavya Shree.R is Chief Marketing Officer at BoostMySites and runs the blog's content calendar. She writes about getting clients with ads, WhatsApp and follow-up systems for growing businesses."}$bmsq$::jsonb, '2026-10-14T03:30:00.000Z', 5, ARRAY[$bmsq$Ads$bmsq$,$bmsq$Meta ads$bmsq$,$bmsq$Budgeting$bmsq$]::text[], 'https://www.boostmysites.com/brand/hero-poster.jpg', $bmsq$Ads$bmsq$, false
WHERE NOT EXISTS (SELECT 1 FROM public.blogs WHERE slug = $bmsq$meta-ads-cost-india$bmsq$);

INSERT INTO public.blogs (title, slug, excerpt, meta_description, content, author, published_date, reading_time, tags, image, category, is_published)
SELECT $bmsq$Agency vs in-house vs AI tool: what client acquisition really costs$bmsq$, $bmsq$agency-vs-in-house-vs-ai-client-acquisition-cost$bmsq$, $bmsq$Compare the real cost of a marketing agency, an in-house hire and an AI client acquisition tool, including hidden costs, and calculate your own number.$bmsq$, $bmsq$Compare the real cost of a marketing agency, an in-house hire and an AI client acquisition tool, including hidden costs, and calculate your own number.$bmsq$, $bmsq$<p>The real cost of client acquisition is ad spend plus everything you pay to run it: fees, salaries, tools, and the time you spend managing it. An agency adds a management fee, an in-house team adds salaries and training time, and an AI tool adds a subscription but still needs your input, so the right choice depends on your budget, how much control you want and who will follow up on leads.</p><p>Owners often compare only the visible fee. That is how a "cheap" option ends up expensive. This guide lists every cost line so you can compare like with like.</p><h2>The three models in one table</h2><table><thead><tr><th>Cost line</th><th>Agency</th><th>In-house</th><th>AI tool / system</th></tr></thead><tbody><tr><td>Ad spend</td><td>Yours, sometimes billed through the agency</td><td>Yours</td><td>Yours</td></tr><tr><td>Management cost</td><td>Monthly retainer or % of spend</td><td>Salary, benefits, recruitment</td><td>Subscription</td></tr><tr><td>Creative production</td><td>Often extra</td><td>Designer time or freelancers</td><td>Varies; check what is included</td></tr><tr><td>Tools</td><td>Usually included or marked up</td><td>Paid separately</td><td>Usually bundled</td></tr><tr><td>Lead follow-up</td><td>Usually not included</td><td>Your sales team</td><td>Can be automated</td></tr><tr><td>Your time</td><td>Meetings, approvals, chasing reports</td><td>Managing the hire</td><td>Approvals and reviewing reports</td></tr><tr><td>Speed of changes</td><td>Depends on their workload</td><td>Depends on your person</td><td>Continuous, within rules you set</td></tr><tr><td>Who owns the ad account</td><td>Check the contract</td><td>You</td><td>Should be you; check</td></tr></tbody></table><h2>Agency: what you pay for and what you do not get</h2><p>A good agency brings experience across many accounts and a team you do not need to manage. The costs to watch are the retainer, any percentage of spend, creative fees, setup fees and minimum contract terms. The hidden cost is often follow-up: most agencies deliver leads to your inbox and stop there. If your team replies the next day, the agency's work loses value. Also ask who owns the ad account and pixel data. If the account sits in the agency's business manager, leaving can mean starting from zero.</p><h2>In-house: control at a price</h2><p>Hiring a performance marketer gives you full control and someone who learns your business deeply. The costs are salary, benefits, recruitment time, tools and the months it takes them to ramp up. One person rarely covers strategy, creative, tracking, ads on several platforms and lead follow-up. If they leave, the knowledge often leaves with them. In-house works best when your spend is large enough to justify a team, not one person stretched across everything.</p><h2>AI tool or AI system: cheaper management, not zero effort</h2><p>AI tools range from simple ad copy generators to full systems that run campaigns, follow up with leads and report results. They can make changes far more often than a human and do not take holidays. But they work within the inputs you give: your offer, your targeting limits, your approval. You still need to approve campaigns, answer qualified leads and keep the offer competitive.</p><p><strong>[EDITOR: add one real example and screenshot here — client name only with written permission]</strong></p><h2>Calculate your own cost per client</h2><p>Use this formula for each option you are considering:</p><p><strong>Total monthly cost</strong> = ad spend + management cost + creative + tools + (your hours × value of your hour)</p><p><strong>Cost per client</strong> = total monthly cost ÷ new paying clients that month</p><h3>Worked example (hypothetical numbers)</h3><p>The figures below are an example to show the method. Replace them with real quotes.</p><table><thead><tr><th>Line</th><th>Agency (example)</th><th>In-house (example)</th><th>AI system (example)</th></tr></thead><tbody><tr><td>Ad spend</td><td>₹1,00,000</td><td>₹1,00,000</td><td>₹1,00,000</td></tr><tr><td>Management</td><td>₹40,000</td><td>₹60,000</td><td>Credits used (pay per action, from ₹899 + GST)</td></tr><tr><td>Creative and tools</td><td>₹15,000</td><td>₹15,000</td><td>Check inclusion</td></tr><tr><td>Owner hours × hourly value</td><td>8 × ₹2,000</td><td>10 × ₹2,000</td><td>4 × ₹2,000</td></tr><tr><td>New clients (example)</td><td>Your data</td><td>Your data</td><td>Your data</td></tr></tbody></table><p>The agency and in-house figures in this table are invented for illustration. The AI system line uses our starting plan price. The bottom row is the one that matters, and only your own tracking can fill it in.</p><h2>Questions to ask before you choose</h2><ul><li>Will the ads run in my own ad account with my own billing?</li><li>Do I approve campaigns before they go live?</li><li>Who replies to leads, and how fast?</li><li>How often are budgets and ads changed, and who decides?</li><li>What report will I get, and will I understand it?</li><li>What is the minimum term and what happens to my data if I leave?</li><li>Does anyone promise guaranteed results? If yes, ask how.</li></ul><h2>Where BoostMySites fits</h2><p>BoostMySites is an AI client acquisition system. It runs ads on Meta, Google, LinkedIn, TikTok, YouTube, Snapchat and ChatGPT ads inside your own ad accounts and billing. Campaigns are staged paused until you approve them. Eight AI agents handle work such as follow-up, where the Follow-up AI messages leads on WhatsApp and email the moment they respond, and a Report Writer sends a weekly plain-English summary. There is no retainer: you buy credits (2,500 credits cost ₹899 + GST in India or $9.99 elsewhere) and they are used only when something is done. We do not guarantee results. See the side-by-side breakdown on our <a href="/compare/vs-agency">AI system vs agency comparison</a>.</p><p>If you are already with an agency and unsure, read <a href="/blog/signs-marketing-agency-wasting-money">7 signs your marketing agency is wasting your money</a>. If you want to understand ad cost first, see <a href="/blog/meta-ads-cost-india">Meta ads cost in India</a>.</p><h2>FAQ</h2><h3>Is an agency always more expensive than an AI tool?</h3><p>Not always. A small agency retainer can cost less than some tools, and a great agency can produce better results than a poorly set up tool. Compare total cost per paying client, not the headline fee.</p><h3>Can I run an AI tool and keep my in-house marketer?</h3><p>Yes, and it is often the best mix. The tool handles repetitive optimisation and follow-up, and your marketer focuses on offers, creative and sales feedback.</p><h3>What is the biggest hidden cost in client acquisition?</h3><p>Slow or missing follow-up. Leads you paid for that nobody contacts in time are pure waste, whichever model you choose.</p><p>Want to see the real cost per client for your business across all three options? <a href="/#contact-form">Get my client acquisition plan</a>.</p>$bmsq$, $bmsq${"name": "Kavya Shree.R", "avatar": "https://www.boostmysites.com/team/kavya.jpg", "bio": "Kavya Shree.R is Chief Marketing Officer at BoostMySites and runs the blog's content calendar. She writes about getting clients with ads, WhatsApp and follow-up systems for growing businesses."}$bmsq$::jsonb, '2026-10-16T03:30:00.000Z', 5, ARRAY[$bmsq$Ads$bmsq$,$bmsq$Agency$bmsq$,$bmsq$Costs$bmsq$]::text[], 'https://www.boostmysites.com/brand/hero-poster.jpg', $bmsq$Ads$bmsq$, false
WHERE NOT EXISTS (SELECT 1 FROM public.blogs WHERE slug = $bmsq$agency-vs-in-house-vs-ai-client-acquisition-cost$bmsq$);

INSERT INTO public.blogs (title, slug, excerpt, meta_description, content, author, published_date, reading_time, tags, image, category, is_published)
SELECT $bmsq$Why your Facebook ads get clicks but no leads$bmsq$, $bmsq$facebook-ads-clicks-but-no-leads$bmsq$, $bmsq$Getting clicks on Facebook ads but no enquiries? Here are the common causes, from audience and offer to landing page and tracking, with a fix for each.$bmsq$, $bmsq$Getting clicks on Facebook ads but no enquiries? Here are the common causes, from audience and offer to landing page and tracking, with a fix for each.$bmsq$, $bmsq$<p>Facebook ads usually get clicks but no leads because something breaks between the click and the enquiry: the campaign is optimised for clicks instead of leads, the landing page or form does not match the ad, the offer is too weak to act on, or tracking is not recording leads that do come in. Work through the checklist below in order, because the cheapest fixes are at the top.</p><p>A click means the ad worked well enough to earn curiosity. A lead means the whole journey worked. So the problem is rarely "Facebook doesn't work for my business". It is usually one or two specific breaks you can find and fix.</p><h2>The diagnostic checklist</h2><ul><li><strong>Campaign objective.</strong> Is it set to Traffic or Engagement? Meta will then find people who click, not people who enquire.</li><li><strong>Tracking.</strong> Is the pixel or Conversions API firing on the thank-you page or lead event? Test it yourself.</li><li><strong>Message match.</strong> Does the landing page repeat the exact promise in the ad?</li><li><strong>Page speed on mobile.</strong> Open the page on a mid-range phone on mobile data. Does it load quickly?</li><li><strong>Form length.</strong> Are you asking for more than you need at this stage?</li><li><strong>Offer.</strong> Is there a clear, specific reason to enquire now?</li><li><strong>Audience.</strong> Are clicks coming from placements or regions you do not serve?</li><li><strong>Accidental clicks.</strong> Are some placements producing a lot of clicks with almost no time on page?</li></ul><h2>1. You are optimising for the wrong thing</h2><p>Meta's delivery system is very good at finding exactly what you ask for. If the objective is traffic, it finds people who click a lot and rarely buy. Switch to a Leads or Sales objective with the right conversion event, or use instant forms or click-to-WhatsApp, so the system learns from people who actually enquire.</p><h2>2. Tracking is broken, so leads look like zero</h2><p>Sometimes leads are arriving but not being counted. Submit a test enquiry and check Events Manager. Check that the thank-you page loads after submission and that the event fires once, not twice. If you use a CRM, make sure form submissions are landing there. A campaign cannot be optimised on data it never receives.</p><h2>3. The landing page breaks the promise</h2><p>If the ad says "2BHK from a fixed price near the metro" and the page opens on a generic homepage with a slider, people leave. Every ad should send people to a page or form that repeats the same headline, shows the same image style and makes the next step obvious. One page, one offer, one action.</p><h2>4. The page is too slow or awkward on a phone</h2><p>Most Meta traffic is mobile. Heavy images, pop-ups, chat widgets covering buttons and forms that need zooming all lose people. Test on a real phone, not your office laptop.</p><h2>5. The form asks too much, or too little</h2><p>Long forms kill volume. Very short instant forms can create the opposite problem: lots of leads who do not remember filling them. Find the middle. Ask only what you need to qualify, and consider one simple qualifying question such as budget range or timeline.</p><h2>6. The offer gives no reason to act</h2><p>"Contact us for more information" is not an offer. Give people something specific: a free consultation with a named outcome, a price guide, a site visit, a sample plan, a limited batch start date. The offer must be real and deliverable.</p><h2>7. Placements and audience are leaking budget</h2><p>Check the breakdown by placement, age, region and device. If one placement produces many clicks but no enquiries, consider excluding it after enough data. Make sure location targeting covers people who live in your area, not just people who once visited it, if that matters for your service.</p><p><strong>[EDITOR: add one real example and screenshot here — client name only with written permission]</strong></p><h2>Clicks vs leads: what each pattern tells you</h2><table><thead><tr><th>What you see</th><th>Most likely cause</th><th>First fix</th></tr></thead><tbody><tr><td>High clicks, low time on page</td><td>Accidental clicks or poor message match</td><td>Check placements; align page headline with ad</td></tr><tr><td>Good time on page, few form starts</td><td>Weak offer or unclear next step</td><td>Sharpen the offer; make the button obvious</td></tr><tr><td>Form starts but few submits</td><td>Form too long or broken on mobile</td><td>Cut fields; test on a phone</td></tr><tr><td>Submits in CRM but zero in Ads Manager</td><td>Tracking problem</td><td>Fix pixel or Conversions API event</td></tr><tr><td>Leads arrive but never answer the phone</td><td>Low intent or slow follow-up</td><td>Add a qualifying question; reply within minutes</td></tr></tbody></table><h2>When the problem is after the lead</h2><p>Sometimes the ads are fine and the issue is what happens next. Leads that wait hours for a reply often stop responding. Set up an instant WhatsApp acknowledgement and a follow-up sequence. See <a href="/blog/whatsapp-follow-up-messages-that-book-demos">15 WhatsApp follow-up messages that book demos</a> for ready-to-use scripts, and <a href="/blog/click-to-whatsapp-ads-setup-guide">the click-to-WhatsApp setup guide</a> if you want to skip forms altogether.</p><h2>How our system catches these issues</h2><p>Our <a href="/services/ai-ad-campaigns">AI ad campaigns</a> run in your own ad account. An optimisation loop checks campaigns every 20 minutes, around 72 checks a day, looking at signals like spend without conversions and weak placements. The Follow-up AI messages leads on WhatsApp and email as soon as they respond, so good leads do not go cold. It cannot fix a weak offer by itself, which is why the offer is the first thing we discuss with you.</p><h2>FAQ</h2><h3>How long should I wait before deciding an ad does not produce leads?</h3><p>Give it enough spend to collect a meaningful number of clicks and a few days for delivery to settle. If tracking is confirmed and many clicks produce zero enquiries, change the offer or page rather than waiting longer.</p><h3>Are instant forms better than landing pages?</h3><p>They usually produce more leads with less friction, but often lower intent. Landing pages produce fewer but warmer leads. Test both and compare cost per qualified lead, not cost per lead.</p><h3>Could my ad account be the problem?</h3><p>Occasionally, for example if payments failed, ads were rejected or the account has restrictions. Check Account Quality in Meta Business Suite before changing anything else.</p><p>Want someone to run this checklist on your account? <a href="/#contact-form">Get my client acquisition plan</a>.</p>$bmsq$, $bmsq${"name": "Kavya Shree.R", "avatar": "https://www.boostmysites.com/team/kavya.jpg", "bio": "Kavya Shree.R is Chief Marketing Officer at BoostMySites and runs the blog's content calendar. She writes about getting clients with ads, WhatsApp and follow-up systems for growing businesses."}$bmsq$::jsonb, '2026-10-19T03:30:00.000Z', 5, ARRAY[$bmsq$Ads$bmsq$,$bmsq$Meta ads$bmsq$,$bmsq$Troubleshooting$bmsq$]::text[], 'https://www.boostmysites.com/brand/hero-poster.jpg', $bmsq$Ads$bmsq$, false
WHERE NOT EXISTS (SELECT 1 FROM public.blogs WHERE slug = $bmsq$facebook-ads-clicks-but-no-leads$bmsq$);

INSERT INTO public.blogs (title, slug, excerpt, meta_description, content, author, published_date, reading_time, tags, image, category, is_published)
SELECT $bmsq$Click-to-WhatsApp ads: setup guide and scripts$bmsq$, $bmsq$click-to-whatsapp-ads-setup-guide$bmsq$, $bmsq$How to set up click-to-WhatsApp ads on Meta step by step, plus opening, qualifying and booking scripts you can copy for your first replies.$bmsq$, $bmsq$How to set up click-to-WhatsApp ads on Meta step by step, plus opening, qualifying and booking scripts you can copy for your first replies.$bmsq$, $bmsq$<p>Click-to-WhatsApp ads are Meta ads on Facebook or Instagram whose button opens a WhatsApp chat with your business instead of a form or website. To set one up, connect a WhatsApp Business number to your Meta business assets, create a campaign with the Engagement or Leads objective and WhatsApp as the conversion location, write a pre-filled greeting, and make sure someone or something replies within minutes.</p><p>They work well for Indian buyers because WhatsApp is where many people already talk to businesses. The weak point is not the ad. It is the reply. A chat that waits hours for an answer is worse than a form, because the buyer expected a conversation.</p><h2>Before you start: checklist</h2><ul><li>A WhatsApp Business app number or a WhatsApp Business Platform (API) number.</li><li>A Meta Business account with your Facebook Page and, ideally, Instagram account connected.</li><li>The WhatsApp number linked to your Page in Meta Business settings.</li><li>An ad account with working billing.</li><li>A greeting and qualifying script ready (see below).</li><li>A named person, or an automation, responsible for replying during the hours ads run.</li><li>A way to log each chat as a lead, even if it is a simple sheet to start.</li></ul><h2>Step-by-step setup</h2><ol><li><strong>Connect WhatsApp to your Page.</strong> In Meta Business settings, link your WhatsApp number to the Facebook Page that will run the ads. Verify the code sent to the number.</li><li><strong>Create the campaign.</strong> In Ads Manager, choose an objective that supports messaging, such as Engagement or Leads, and choose WhatsApp as the conversion location. Meta's options change from time to time, so follow what Ads Manager shows you.</li><li><strong>Set location and audience.</strong> Target only where you can actually serve. Start broad within that area and let the system learn.</li><li><strong>Write the creative.</strong> Say who it is for, what they get and why to chat now. End with a reason to tap: "Chat with us for today's price list".</li><li><strong>Set the message template.</strong> Add a greeting and, if offered, quick-reply questions such as "What's the price?" or "Book a visit". These make the first tap easy.</li><li><strong>Prepare replies before going live.</strong> Use the scripts below. If you use the API, set up an automated first reply.</li><li><strong>Launch with a small budget,</strong> watch the first conversations closely, and refine the script based on what people actually ask.</li></ol><h2>Business app or API?</h2><table><thead><tr><th></th><th>WhatsApp Business app</th><th>WhatsApp Business Platform (API)</th></tr></thead><tbody><tr><td>Setup</td><td>Simple, on a phone</td><td>Needs a provider or developer setup</td></tr><tr><td>Multiple team members</td><td>Limited</td><td>Yes, via a shared inbox</td></tr><tr><td>Automation</td><td>Basic greeting and away messages</td><td>Full automation and CRM sync</td></tr><tr><td>Cost</td><td>Free app</td><td>Meta charges by message category, plus provider fees</td></tr><tr><td>Best for</td><td>Testing with low volume</td><td>Steady volume and a team</td></tr></tbody></table><p>For more detail on API costs, read <a href="/blog/whatsapp-business-api-pricing-india">WhatsApp Business API pricing in India explained</a>. Meta has also offered free messaging windows for conversations started from these ads, so check the current terms on Meta's pricing page.</p><h2>Scripts for your first replies</h2><h3>Opening reply (send instantly)</h3><p>"Hi, thanks for messaging [Business]. I'm [Name]. To share the right details, can I ask two quick questions?"</p><h3>Qualifying questions (one at a time)</h3><ul><li>Real estate: "Are you looking for 2BHK or 3BHK, and roughly when are you planning to move?"</li><li>Clinic: "Is this for you or a family member, and which concern would you like to discuss?"</li><li>Interior design: "Is this a new home or a renovation, and which rooms are you planning?"</li><li>Coaching: "Which exam are you preparing for, and which year will you appear?"</li><li>B2B service: "What does your business do, and what made you look into this now?"</li></ul><h3>Value reply</h3><p>"Thanks. Based on that, here is [price list / sample plan / brochure]. Most people in your situation start with [specific next step]."</p><h3>Booking ask</h3><p>"Would a 15-minute call today or tomorrow help? I have [slot 1] or [slot 2]."</p><h3>If they go quiet</h3><p>"Just checking you got the [document]. Happy to answer any question here on chat if a call isn't convenient."</p><p><strong>[EDITOR: add one real example and screenshot here — client name only with written permission]</strong></p><h2>Mistakes to avoid</h2><ul><li>Sending a long paragraph as the first reply. Keep it short and ask one question.</li><li>Asking for a phone call immediately. They chose chat for a reason.</li><li>Running ads at night when nobody can reply, unless you have automation.</li><li>Not tagging chats as leads, so you cannot tell which ads produced paying clients.</li><li>Sending a price list with no follow-up question.</li></ul><p>For the follow-up messages after the first conversation, use <a href="/blog/whatsapp-follow-up-messages-that-book-demos">these 15 WhatsApp follow-ups</a>.</p><h2>How we automate it</h2><p>With our <a href="/services/whatsapp-automation">WhatsApp automation</a>, the Follow-up AI answers new chats the moment they arrive, asks your qualifying questions, and sends scored leads into your CRM so your team calls the warm ones first. The ads run in your own Meta account and stay paused until you approve them.</p><h2>FAQ</h2><h3>Can I run click-to-WhatsApp ads with the free WhatsApp Business app?</h3><p>Yes. It is a good way to test. Once volume grows or several people need to reply, the API with a shared inbox becomes easier to manage.</p><h3>Are click-to-WhatsApp leads better than form leads?</h3><p>They are different. Chats are often warmer because the person started a conversation, but they need fast replies. Compare cost per qualified lead from both for your business.</p><h3>Can I send them messages later?</h3><p>Within WhatsApp's customer service window after their last message you can reply freely. After it closes, you need an approved template message, and you should only message people who are happy to hear from you.</p><p>Want click-to-WhatsApp ads and instant replies set up for you? <a href="/#contact-form">Get my client acquisition plan</a>.</p>$bmsq$, $bmsq${"name": "Kavya Shree.R", "avatar": "https://www.boostmysites.com/team/kavya.jpg", "bio": "Kavya Shree.R is Chief Marketing Officer at BoostMySites and runs the blog's content calendar. She writes about getting clients with ads, WhatsApp and follow-up systems for growing businesses."}$bmsq$::jsonb, '2026-10-21T03:30:00.000Z', 5, ARRAY[$bmsq$WhatsApp$bmsq$,$bmsq$Meta ads$bmsq$,$bmsq$Scripts$bmsq$]::text[], 'https://www.boostmysites.com/brand/hero-poster.jpg', $bmsq$WhatsApp$bmsq$, false
WHERE NOT EXISTS (SELECT 1 FROM public.blogs WHERE slug = $bmsq$click-to-whatsapp-ads-setup-guide$bmsq$);

INSERT INTO public.blogs (title, slug, excerpt, meta_description, content, author, published_date, reading_time, tags, image, category, is_published)
SELECT $bmsq$WhatsApp Business API pricing in India explained$bmsq$, $bmsq$whatsapp-business-api-pricing-india$bmsq$, $bmsq$How WhatsApp Business API pricing works in India: Meta's message categories, provider fees and hidden costs, plus a formula to estimate your monthly bill.$bmsq$, $bmsq$How WhatsApp Business API pricing works in India: Meta's message categories, provider fees and hidden costs, plus a formula to estimate your monthly bill.$bmsq$, $bmsq$<p>WhatsApp Business API pricing in India has two parts: what Meta charges for messages, which depends on the message category (marketing, utility, authentication or service) and the recipient's country, and what your provider charges for the platform, inbox and support. Meta's rates and rules change over time, so always check Meta's current rate card before budgeting, and use the formula below to estimate your own bill.</p><p>This post does not quote per-message rates on purpose. Any rate printed in a blog post will be out of date sooner or later, and the right number for you depends on your mix of messages. What does not change much is how the bill is built.</p><h2>The two layers of cost</h2><h3>1. Meta's charges</h3><p>Meta, which owns WhatsApp, charges businesses for certain messages sent through the WhatsApp Business Platform. The price depends on:</p><ul><li><strong>Category of message.</strong> Meta groups business messages into categories such as marketing (offers, announcements), utility (order updates, appointment reminders), authentication (one-time passwords) and service (replies to customers who messaged you). Each category is priced differently, and some may be free in certain situations.</li><li><strong>Recipient's country.</strong> Rates are set by the country code of the person receiving the message, not where your business is. Messaging a customer in the UAE from India is priced at the UAE rate.</li><li><strong>Whether a customer service window is open.</strong> When a customer messages you, a window opens in which you can reply freely. Meta treats many messages inside that window differently from template messages you send cold.</li><li><strong>The current billing model.</strong> Meta has changed how it bills over time, for example moving from conversation-based charging toward per-message charging for templates. Check which model applies today.</li></ul><p>The official source is Meta's WhatsApp Business Platform pricing page and rate card. Check it directly before you budget, and check again every few months.</p><h3>2. Your provider's charges</h3><p>Most businesses use a Business Solution Provider (BSP) or a software platform rather than building directly on Meta's Cloud API. Providers charge in different ways:</p><ul><li>A monthly platform or seat fee for the shared inbox and automation tools.</li><li>A markup on Meta's message charges, or Meta's charges passed through at cost.</li><li>One-time setup or onboarding fees.</li><li>Extra fees for chatbots, CRM integrations, extra numbers or extra team members.</li><li>GST on top of the above.</li></ul><p>Two providers can quote very different totals for the same message volume. Ask each one for a written breakdown.</p><h2>How to estimate your monthly bill</h2><p>Split your planned messages by category, then apply the current rates from Meta's rate card and your provider's quote.</p><p><strong>Monthly Meta cost</strong> = (marketing messages × marketing rate) + (utility messages × utility rate) + (authentication messages × authentication rate) + (paid service messages × service rate, if any)</p><p><strong>Total monthly cost</strong> = Meta cost + provider markup + platform fee + GST</p><h3>Worked example (example volumes, rates left as letters)</h3><p>The volumes below are an example. We have left the rates as letters on purpose, so you fill them in from Meta's current rate card and your provider's quote rather than trusting a number that may be out of date.</p><table><thead><tr><th>Message type</th><th>Example volume per month</th><th>Rate (from current rate card)</th><th>Cost</th></tr></thead><tbody><tr><td>Marketing templates (offers, re-engagement)</td><td>2,000</td><td>M</td><td>2,000 × M</td></tr><tr><td>Utility templates (reminders, confirmations)</td><td>1,000</td><td>U</td><td>1,000 × U (check if free inside an open window)</td></tr><tr><td>Authentication (OTPs)</td><td>0</td><td>A</td><td>0</td></tr><tr><td>Service replies inside open window</td><td>3,000</td><td>Check current terms</td><td>Often small or nil; confirm</td></tr><tr><td>Provider platform fee</td><td>—</td><td>P (from quote)</td><td>P</td></tr><tr><td><strong>Total before GST</strong></td><td></td><td></td><td><strong>2,000M + 1,000U + P + markup</strong></td></tr></tbody></table><p>The point of the example is the shape: for most lead-generation businesses, marketing templates and the provider fee drive the bill. Replies to people who messaged you first are usually a smaller part of it.</p><p><strong>[EDITOR: insert our real account data here — a typical monthly WhatsApp cost breakdown for one of our clients by category, with the date of the rate card used. Keep the letter-based example alongside it.]</strong></p><p><strong>[EDITOR: add one real example and screenshot here — client name only with written permission]</strong></p><h2>How to keep the bill down</h2><ul><li><strong>Let customers start the conversation.</strong> Click-to-WhatsApp ads and "chat with us" buttons mean you are replying, not cold messaging. See the <a href="/blog/click-to-whatsapp-ads-setup-guide">click-to-WhatsApp setup guide</a>.</li><li><strong>Reply while the window is open.</strong> Answer fast so you can follow up freely instead of paying for a template later.</li><li><strong>Categorise templates honestly.</strong> Meta reviews templates and can recategorise a "utility" message that is really marketing.</li><li><strong>Do not blast your whole list.</strong> Send marketing templates only to people likely to care. It costs less and protects your number's quality rating.</li><li><strong>Stop sequences when people reply.</strong> Every automated message after a reply is wasted.</li></ul><h2>Questions to ask a provider</h2><ul><li>Do you pass Meta's charges at cost or add a markup? How much?</li><li>What is the monthly platform fee, and what does it include?</li><li>Are there setup, number or per-user fees?</li><li>Who owns the WhatsApp Business account and number if I leave?</li><li>Can you show me a sample invoice?</li></ul><h2>Where we fit</h2><p>Our <a href="/services/whatsapp-automation">WhatsApp automation</a> is part of the BoostMySites client acquisition system. The Follow-up AI replies to new leads the moment they respond, which keeps most follow-up inside the open window. For good templates to use when the window has closed, see <a href="/blog/whatsapp-follow-up-messages-that-book-demos">15 WhatsApp follow-up messages that book demos</a>.</p><h2>FAQ</h2><h3>Is the WhatsApp Business app free?</h3><p>The WhatsApp Business app on a phone is free to use. The charges described here apply to the WhatsApp Business Platform (API), which you need for team inboxes, automation and higher volume.</p><h3>Do I pay for messages customers send me?</h3><p>Meta's charges apply to certain messages you send, not to messages you receive. Check Meta's current pricing page for which replies are free and under what conditions.</p><h3>Why did my WhatsApp bill go up when I sent the same number of messages?</h3><p>Possible reasons include a change in Meta's rates, a template being recategorised to marketing, messaging more contacts in other countries, or a change in your provider's fees. Ask your provider for a breakdown by category and country.</p><p>Want WhatsApp follow-up set up with a clear cost estimate first? <a href="/#contact-form">Get my client acquisition plan</a>.</p>$bmsq$, $bmsq${"name": "Kavya Shree.R", "avatar": "https://www.boostmysites.com/team/kavya.jpg", "bio": "Kavya Shree.R is Chief Marketing Officer at BoostMySites and runs the blog's content calendar. She writes about getting clients with ads, WhatsApp and follow-up systems for growing businesses."}$bmsq$::jsonb, '2026-10-23T03:30:00.000Z', 5, ARRAY[$bmsq$WhatsApp$bmsq$,$bmsq$WhatsApp API$bmsq$,$bmsq$Pricing$bmsq$]::text[], 'https://www.boostmysites.com/brand/hero-poster.jpg', $bmsq$WhatsApp$bmsq$, false
WHERE NOT EXISTS (SELECT 1 FROM public.blogs WHERE slug = $bmsq$whatsapp-business-api-pricing-india$bmsq$);

INSERT INTO public.blogs (title, slug, excerpt, meta_description, content, author, published_date, reading_time, tags, image, category, is_published)
SELECT $bmsq$15 WhatsApp follow-up messages that book demos$bmsq$, $bmsq$whatsapp-follow-up-messages-that-book-demos$bmsq$, $bmsq$15 short WhatsApp follow-up messages you can copy, organised by timing, to turn new leads into booked demos and calls without sounding pushy.$bmsq$, $bmsq$15 short WhatsApp follow-up messages you can copy, organised by timing, to turn new leads into booked demos and calls without sounding pushy.$bmsq$, $bmsq$<p>The WhatsApp follow-ups that book demos are short, personal, and each one gives the lead an easy reason to reply: a question, a useful file, or two specific time slots. Send the first within minutes of the enquiry, space the rest over about two weeks, and stop as soon as the person responds.</p><p>Below are 15 messages grouped by when to send them. Replace the brackets with your details. Keep your tone natural; read each one aloud before sending and change anything that sounds like a template.</p><h2>The sequence at a glance</h2><table><thead><tr><th>Stage</th><th>Timing</th><th>Messages</th><th>Goal</th></tr></thead><tbody><tr><td>Instant</td><td>Within minutes</td><td>1–3</td><td>Acknowledge and qualify</td></tr><tr><td>Same day / next day</td><td>Hours to day 1</td><td>4–6</td><td>Share value and ask for a slot</td></tr><tr><td>Nudge</td><td>Days 2–7</td><td>7–10</td><td>Remove doubts, offer alternatives</td></tr><tr><td>Last tries</td><td>Days 8–14</td><td>11–12</td><td>Close the loop politely</td></tr><tr><td>After booking</td><td>Before and after demo</td><td>13–15</td><td>Make sure they show up</td></tr></tbody></table><p>One rule before you copy anything: WhatsApp lets you reply freely only for a period after the customer's last message. Outside that window you must use Meta-approved templates, so submit the later messages as templates if you use the API. And only message people who gave you their number to hear from you.</p><h2>Instant (within minutes)</h2><p><strong>1. The acknowledgement</strong><br>"Hi [Name], this is [Your name] from [Business]. Got your enquiry about [service]. Can I ask one quick question so I send the right details?"</p><p><strong>2. The qualifier</strong><br>"Thanks. Is this for [option A] or [option B], and roughly when are you hoping to start?"</p><p><strong>3. The useful file</strong><br>"Here is our [price guide / sample report / brochure] for [option]. Have a look and tell me what you'd like to know more about."</p><h2>Same day or next day</h2><p><strong>4. The slot offer</strong><br>"A 15-minute call is usually the quickest way to see if we're a fit. Does [today 5 pm] or [tomorrow 11 am] work?"</p><p><strong>5. The demo framing</strong><br>"On the call I'll show you [specific thing, e.g. how the dashboard looks for a business like yours]. No slides, just your questions."</p><p><strong>6. The voice note option</strong><br>"If typing is easier, send me a voice note with your questions and I'll reply the same way."</p><h2>Nudge (days 2–7)</h2><p><strong>7. The common question</strong><br>"Many people ask us [common question]. Short answer: [answer in one line]. Happy to explain on a call."</p><p><strong>8. The proof message</strong><br>"Here's a short example of work we did for a [type of business] in [city]. Similar situation to yours." (Only share work you have permission to show.)</p><p><strong>9. The alternative format</strong><br>"If a call is hard this week, I can send a 3-minute video walkthrough instead. Want me to?"</p><p><strong>10. The direct question</strong><br>"Quick check, [Name]: is this still something you're looking at, or should I follow up later?"</p><h2>Last tries (days 8–14)</h2><p><strong>11. The timing check</strong><br>"Totally understand if now isn't the right time. Should I check back in [month]?"</p><p><strong>12. The polite close</strong><br>"I'll stop messaging so I don't crowd your WhatsApp. If you want to pick this up later, just reply 'hi' and I'll get back to you."</p><h2>After booking</h2><p><strong>13. The confirmation</strong><br>"Confirmed for [day, time]. I'll call you on this number. If anything changes, reply here and we'll move it."</p><p><strong>14. The reminder</strong><br>"Hi [Name], reminder about our call at [time] today. Anything specific you'd like me to cover?"</p><p><strong>15. The no-show rescue</strong><br>"Looks like we missed each other. No problem. Would [slot 1] or [slot 2] work better?"</p><p><strong>[EDITOR: add one real example and screenshot here — client name only with written permission]</strong></p><h2>Checklist: what makes these work</h2><ul><li>Every message ends with something easy to reply to.</li><li>No message is longer than a phone screen.</li><li>Specific time slots instead of "let me know when you're free".</li><li>One idea per message.</li><li>Your real name, not just the company name.</li><li>The sequence stops the moment they reply, and a human or AI takes over the conversation.</li><li>Every opt-out request is honoured immediately.</li></ul><h2>What to avoid</h2><ul><li>"Just following up" with nothing new to say.</li><li>Sending all your brochures at once.</li><li>Pressure lines like "offer ends tonight" when it doesn't.</li><li>Messaging late at night or very early in the morning.</li><li>Copying the same text as your last message.</li></ul><h2>Timing matters more than wording</h2><p>The best script in the world will not save a lead you reply to the next afternoon. Read <a href="/blog/how-fast-should-you-reply-to-a-lead">how fast should you reply to a lead</a> before you polish the copy. And if you are paying for messages through the API, check <a href="/blog/whatsapp-business-api-pricing-india">how WhatsApp API pricing works</a> so your sequence stays affordable.</p><h2>Automating the sequence</h2><p>With our <a href="/services/whatsapp-automation">WhatsApp automation</a>, the Follow-up AI sends the instant messages the moment a lead responds, asks your qualifying questions, offers slots, and hands over to your team when the lead is ready. Leads are scored and pushed into your CRM, so you see who to call first.</p><h2>FAQ</h2><h3>How many follow-up messages are too many?</h3><p>If each message adds something new and you stop when they reply or opt out, a sequence across about two weeks is reasonable. Repeating the same ask every day is too many.</p><h3>Should I use voice notes for follow-up?</h3><p>Voice notes feel personal and work well for some audiences, but not everyone can listen at work. Offer both and let the lead choose.</p><h3>Can these messages be sent automatically?</h3><p>Yes, using the WhatsApp Business Platform with approved templates for messages outside the customer service window. Keep personalisation fields accurate, because a wrong name feels worse than no name.</p><p>Want this sequence written for your business and running on WhatsApp? <a href="/#contact-form">Get my client acquisition plan</a>.</p>$bmsq$, $bmsq${"name": "Kavya Shree.R", "avatar": "https://www.boostmysites.com/team/kavya.jpg", "bio": "Kavya Shree.R is Chief Marketing Officer at BoostMySites and runs the blog's content calendar. She writes about getting clients with ads, WhatsApp and follow-up systems for growing businesses."}$bmsq$::jsonb, '2026-10-26T03:30:00.000Z', 5, ARRAY[$bmsq$WhatsApp$bmsq$,$bmsq$Follow-up$bmsq$,$bmsq$Scripts$bmsq$]::text[], 'https://www.boostmysites.com/brand/hero-poster.jpg', $bmsq$WhatsApp$bmsq$, false
WHERE NOT EXISTS (SELECT 1 FROM public.blogs WHERE slug = $bmsq$whatsapp-follow-up-messages-that-book-demos$bmsq$);

INSERT INTO public.blogs (title, slug, excerpt, meta_description, content, author, published_date, reading_time, tags, image, category, is_published)
SELECT $bmsq$How fast should you reply to a lead?$bmsq$, $bmsq$how-fast-should-you-reply-to-a-lead$bmsq$, $bmsq$Reply to new leads within minutes, while they are still on their phone. Here is why speed matters, how to measure it and how to fix slow follow-up.$bmsq$, $bmsq$Reply to new leads within minutes, while they are still on their phone. Here is why speed matters, how to measure it and how to fix slow follow-up.$bmsq$, $bmsq$<p>You should reply to a new lead within minutes, ideally while they are still holding the phone they used to enquire. The longer you wait, the more likely they have spoken to a competitor, forgotten the ad, or moved on with their day, so treat response time as a number you measure every week, not a habit you hope for.</p><p>You will see many confident statistics online about how much reply speed matters. We would rather you measure it in your own business. The logic is simple enough to accept without a study, and the fix is cheap.</p><h2>Why speed matters, in plain terms</h2><ul><li><strong>Attention is short.</strong> Someone who tapped an ad between other tasks has their attention on you for a few minutes. After that, your message competes with everything else on their phone.</li><li><strong>Buyers enquire with several businesses.</strong> The first one to reply helpfully sets the frame for the whole conversation.</li><li><strong>Memory fades.</strong> A lead called the next day often says "which company is this?" That conversation starts from zero.</li><li><strong>You already paid for the lead.</strong> Every lead that goes cold raises your real cost per client, even if the ad dashboard looks fine.</li></ul><h2>Response time targets</h2><table><thead><tr><th>Reply time</th><th>What the lead experiences</th><th>What to do</th></tr></thead><tbody><tr><td>Within minutes</td><td>"They are on it." Conversation feels live.</td><td>Your target. Automate the first reply if needed.</td></tr><tr><td>Within an hour</td><td>Acceptable, but they may have contacted others.</td><td>Fine for complex B2B, weak for consumer services.</td></tr><tr><td>Same day</td><td>Interest has cooled. Needs re-explaining.</td><td>Fix the process. This is where paid leads leak.</td></tr><tr><td>Next day or later</td><td>Often forgotten or already decided.</td><td>Treat as a re-activation, not a fresh lead.</td></tr></tbody></table><h2>How to measure your current response time</h2><ol><li>Take the last 30 leads from your CRM or sheet.</li><li>For each, note the time the lead arrived and the time of your first real reply (not an auto-reply that says nothing).</li><li>Calculate the median gap, plus the share of leads answered within your target.</li><li>Break it down by hour and day. Most teams find evenings, weekends and lunch hours are the problem.</li><li>Repeat monthly.</li></ol><p>Our <a href="/tools/lead-response-calculator">lead response calculator</a> helps you put a rupee value on the gap, using your own lead volume, close rate and deal value.</p><h3>Worked example (hypothetical numbers)</h3><p>The numbers here are an example only. Imagine a business gets 100 leads a month, closes 8 of every 100 leads it replies to quickly, and closes fewer of the leads it replies to late. If 40 leads a month are answered late, and late leads close at half the rate, that is 40 × 8% × 50% = about 1.6 clients lost per month. Multiply by your average deal value to see the monthly cost. With your real numbers, the result is often bigger than the cost of fixing the process.</p><p><strong>[EDITOR: add one real example and screenshot here — client name only with written permission]</strong></p><h2>How to reply faster without hiring</h2><ul><li><strong>Send an instant, useful first message.</strong> Not "we received your request", but a greeting plus one qualifying question.</li><li><strong>Route leads to one owner.</strong> When a lead goes to a shared inbox, everyone assumes someone else will reply.</li><li><strong>Push notifications to phones.</strong> Leads sitting in an email inbox are leads waiting.</li><li><strong>Prepare saved replies.</strong> Price list, brochure, location, slot offers. Answering should take seconds.</li><li><strong>Cover off-hours.</strong> Either pause ads when nobody can reply, or automate replies at night and on weekends.</li><li><strong>Score leads.</strong> Call the warmest first. See <a href="/blog/lead-scoring-small-teams">lead scoring for small teams</a>.</li></ul><h2>What a good first reply looks like</h2><p>Speed only helps if the message is worth reading. Good first replies use the lead's name, mention what they asked about, and ask one easy question. For copy-ready examples, see <a href="/blog/whatsapp-follow-up-messages-that-book-demos">15 WhatsApp follow-up messages that book demos</a>.</p><h2>Speed by channel</h2><p>Different channels set different expectations. Someone who taps a click-to-WhatsApp ad expects a chat reply almost immediately, because the app feels live. Someone who fills a form on your website expects a call or message soon, but may tolerate a short wait. A B2B buyer who emails a detailed brief expects a considered answer, though even then a quick "got it, here is when you'll hear from us" keeps them from looking elsewhere. Set a target for each channel, write it down, and share it with whoever handles leads. A target nobody knows about is not a target.</p><h2>Where automation helps and where it does not</h2><p>Automation is excellent at the first reply and the routine follow-ups. It never sleeps and never forgets. It is not a replacement for a knowledgeable human when the buyer has a complex question or is ready to negotiate. The best setup uses AI for speed and humans for judgement. In the BoostMySites system, the Follow-up AI messages leads on WhatsApp and email the moment they respond, scores them, and pushes them into your CRM so your team picks up warm conversations instead of cold names.</p><h2>FAQ</h2><h3>Is an automatic "thank you" message enough?</h3><p>Only if it moves the conversation forward. A message that asks a qualifying question or shares something useful counts. A generic receipt does not, and the lead knows it.</p><h3>What if leads come in at night?</h3><p>Either schedule ads to run when someone can reply, or use automation to reply instantly and book a call for the morning. Do not leave paid leads waiting until the next afternoon.</p><h3>Should I call or WhatsApp a new lead first?</h3><p>It depends on how they enquired and on your audience. Many people prefer a message first and a call at a time they choose. A quick WhatsApp asking when is good to talk often gets a better response than an unexpected call.</p><p>Want to see how much slow replies are costing you, and fix it? <a href="/#contact-form">Get my client acquisition plan</a>.</p>$bmsq$, $bmsq${"name": "Kavya Shree.R", "avatar": "https://www.boostmysites.com/team/kavya.jpg", "bio": "Kavya Shree.R is Chief Marketing Officer at BoostMySites and runs the blog's content calendar. She writes about getting clients with ads, WhatsApp and follow-up systems for growing businesses."}$bmsq$::jsonb, '2026-10-28T03:30:00.000Z', 5, ARRAY[$bmsq$WhatsApp$bmsq$,$bmsq$Follow-up$bmsq$,$bmsq$Sales process$bmsq$]::text[], 'https://www.boostmysites.com/brand/hero-poster.jpg', $bmsq$WhatsApp$bmsq$, false
WHERE NOT EXISTS (SELECT 1 FROM public.blogs WHERE slug = $bmsq$how-fast-should-you-reply-to-a-lead$bmsq$);

